let state={page:location.hash.slice(1)||'home',selectedRoom:1,search:'',type:'ทั้งหมด',selectedSlot:null,calendarView:'week',calendarRoom:1,bookingFilter:'all'};
let bookings=JSON.parse(localStorage.getItem('roomBookings')||'[]');
let issueReports=JSON.parse(localStorage.getItem('issueReports')||'[]');
function isAdmin(){return sessionStorage.getItem('role')==='admin'}
function save(){localStorage.setItem('roomBookings',JSON.stringify(bookings))}
function room(id){return rooms.find(r=>r.id===Number(id))||rooms[0]}
function go(page){state.page=page;location.hash=page;render()}
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'home';render()});
function shell(content){if(isAdmin())return adminShell(content);return `<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-icon">น</div><div><strong>ระบบจองห้อง</strong><small>มหาวิทยาลัยราชภัฏอุบลราชธานี</small></div></div><nav class="side-nav">${nav.map(n=>`<a class="side-link ${state.page===n[0]||state.page==='detail'&&n[0]==='search'?'active':''}" href="#${n[0]}"><i class="bi bi-${n[2]}"></i><span>${n[1]}</span></a>`).join('')}</nav><div class="profile"><i class="bi bi-person-fill"></i><div class="profile-info"><strong>นมิตา จอมบุญ</strong><small>นักศึกษาปีที่ 3 • วท.บ.</small></div><button class="logout-btn" onclick="logout()" title="ออกจากระบบ"><i class="bi bi-box-arrow-right"></i></button></div></aside><main class="main">${content}</main></div>`}
function adminShell(content){return `<div class="app admin-app"><aside class="sidebar admin-sidebar"><div class="brand"><div class="brand-icon admin-mark">อ</div><div><strong>ระบบผู้ดูแลระบบ</strong><small>สำนักงานคณะเกษตรศาสตร์</small></div></div><nav class="side-nav">${adminNav.map(n=>`<a class="side-link ${state.page===n[0]?'active':''}" href="#${n[0]}"><i class="bi bi-${n[2]}"></i><span>${n[1]}</span></a>`).join('')}</nav><div class="profile"><i class="bi bi-person-fill"></i><div class="profile-info"><strong>แอดมิน</strong><small>ผู้ดูแลระบบ</small></div><button class="logout-btn" onclick="logout()" title="ออกจากระบบ"><i class="bi bi-box-arrow-right"></i></button></div></aside><main class="main">${content}</main></div>`}
function head(title,desc){let isDark=document.body.classList.contains('dark-mode');let adminBadge=isAdmin()?'<span class="notify-badge">5</span>':'';return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions"><button class="theme-toggle" onclick="toggleTheme()" title="สลับโหมดสี"><i class="bi bi-${isDark?'sun':'moon-stars'}"></i></button><button class="notify" onclick="go('notifications')"><i class="bi bi-bell"></i>${adminBadge}</button></div></div>`}
function roomCard(r){return `<article class="room-card"><img class="room-img" src="${r.img}" alt="${r.name}"><div class="room-body"><span class="room-tag">${r.type}</span><h3>${r.name}</h3><div class="muted">${r.building}</div><div class="room-meta"><span><i class="bi bi-people"></i> ความจุ ${r.capacity} คน</span><span><i class="bi bi-projector"></i><i class="bi bi-wifi"></i></span></div><button class="btn-green" onclick="state.selectedRoom=${r.id};go('detail')">ดูรายละเอียด</button></div></article>`}
function home(){return head('ยินดีต้อนรับสู่ระบบจองห้อง','ค้นหาและสำรองห้องเรียน ห้องประชุม หรือห้องปฏิบัติการภายในมหาวิทยาลัยได้อย่างรวดเร็ว')+`<div class="searchbar"><button class="btn-green" onclick="go('search')"><i class="bi bi-plus-lg"></i> จองห้องเรียน/ห้องประชุม</button><div class="search-input"><i class="bi bi-search"></i><input class="form-control" placeholder="ค้นหาชื่อห้องหรืออาคาร..." oninput="state.search=this.value;render()"></div><button class="btn-outline"><i class="bi bi-calendar3"></i> ระบุวันที่จอง</button><button class="btn-outline"><i class="bi bi-clock"></i> ระบุเวลา</button><button class="btn-green" onclick="go('search')">ค้นหา</button></div><h2 class="section-title">ประเภทห้องที่มี</h2><div class="room-grid">${rooms.map(roomCard).join('')}</div><div class="panel mt-4"><div class="d-flex justify-content-between"><h2 class="section-title">ประกาศจากผู้ดูแลระบบ</h2><a href="#rules" class="text-success small">ดูทั้งหมด</a></div><div class="notice-row"><span class="status pending">เปิดรับปรุง</span> ขอให้บริการห้องประชุม 3 อาคาร 51 ในวันเสาร์ที่ 15 เนื่องจากปรับปรุงระบบเครือข่าย</div><div class="notice-row mt-2"><span class="status approved">ข่าวประชาสัมพันธ์</span> เริ่มเปิดให้จองห้องประชุมล่วงหน้าได้ตั้งแต่วันนี้</div></div>`}
